    $t=$p['tenant'];if(b52Voor($state['stage'],'tenant_provisioned')){b52Child($current,'provision-tenant.php',['--key='.$t['key'],'--name='.$t['name'],'--url='.$t['url'],'--root='.$p['paths']['tenant_base'],'--timezone=Europe/Amsterdam','--driver=pdo','--modules='.implode(',',$t['modules'])]);b52Checkpoint($p,$state,'tenant_provisioned');}
    if(b52Voor($state['stage'],'tenant_admin_ready')){if(!b52TenantMasterExists($p))b52Ok(['/usr/bin/php',$current.'/bin/bootstrap-tenant-admin.php','--config='.$t['config_file'],'--password-stdin'],$secrets['tenant_admin_password']."\n");if(!b52TenantMasterExists($p))throw new RuntimeException('Tenantbeheerder kon niet worden bewezen.');b52Checkpoint($p,$state,'tenant_admin_ready');}
    foreach($secrets as$k=>$v){$secrets[$k]=str_repeat("\0",strlen($v));}unset($secrets,$v);
    if(b52Voor($state['stage'],'tenant_plans_ready')){b52PrepareTenantPlans($p,$current);b52Checkpoint($p,$state,'tenant_plans_ready');}
    if(b52Voor($state['stage'],'tenant_runtime_applied')){b52TenantApplyRuntime($p,$current);b52Checkpoint($p,$state,'tenant_runtime_applied');}
    if(b52Voor($state['stage'],'tenant_database_applied')){b52TenantDb($p,$current);b52Checkpoint($p,$state,'tenant_database_applied');}
    if(b52Voor($state['stage'],'tenant_fpm_active')){b52TenantFpm($p);b52Checkpoint($p,$state,'tenant_fpm_active');}
    if(b52Voor($state['stage'],'tenant_dns_ready')){b52TenantDns($p,$current);b52Checkpoint($p,$state,'tenant_dns_ready');}
    if(b52Voor($state['stage'],'tenant_tls_active')){b52TenantTls($p,$current);b52Checkpoint($p,$state,'tenant_tls_active');}
    if(b52Voor($state['stage'],'tenant_monitoring_active')){b52TenantMonitoring($p,$current);b52Checkpoint($p,$state,'tenant_monitoring_active');}
    if(b52Voor($state['stage'],'tenant_lifecycle_active')){b52TenantLifecycle($p,$current);b52Checkpoint($p,$state,'tenant_lifecycle_active');}
    if(b52Voor($state['stage'],'complete')){b52Final($p,$current);b52Checkpoint($p,$state,'complete');}
    echo'BOOTSTRAP OK commit='.$p['commit'].' platform='.$p['platform']['host'].' tenant='.$p['tenant']['key']."\n";
}catch(Throwable$e){b52Stop($e->getMessage());}
